import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('routes recovery to the minimal payment context', async () => {
  const agents = await readFile(new URL('../AGENTS.md', import.meta.url), 'utf8');
  const source = await readFile(new URL('../src/payments/resume.ts', import.meta.url), 'utf8');
  assert.match(agents, /guides\/payments\.md/);
  assert.match(source, /verify-refund-boundary/);
});
